input.command:
d=$(mktemp -d); git archive feat/BKG-80 | tar -x -C "$d"; cd "$d"; 
echo "--- check"; bash tools/check; 
echo "--- missing file"; ARCHIVE=/nonexistent bash tools/purge-archive --dry-run; echo "rc=$?";
echo "--- header only"; printf '# h\n' > h.tsv; ARCHIVE=h.tsv bash tools/purge-archive --dry-run; echo rc=$?;
echo "--- default data"; wc -l data/archive.tsv; bash tools/purge-archive --dry-run; echo rc=$?; git -C /app status --short
echo "--- extra args / --all with dry"; ARCHIVE=h.tsv bash tools/purge-archive --dry-run --all; echo rc=$?
echo "--- no tmp leftover"; ls data
